save(s)

# ---------- 252 ----------
s=mk(252,'pH and [H⁺] · pOH · pKw · Equations 8.6–8.8','pH اور [H⁺] · pOH · pKw · مساوات 8.6–8.8','pH او [H⁺] · pOH · pKw · معادلې 8.6–8.8','poh-pkw')
F=Flow(s)
add(s,'a1','It must be noted that the pH increases as [H⁺] decreases.','یہ نوٹ کرنا ضروری ہے کہ [H⁺] کم ہونے پر pH بڑھتا ہے۔','دا باید په یاد وي چې کله [H⁺] کمېږي pH زیاتېږي.')
add(s,'a2','If you know the pH value of a solution and want to calculate the H⁺ ion concentration, then you need to take the antilog of equation (8.5) as follows,','اگر آپ کو کسی محلول کا pH معلوم ہو اور H⁺ آئن کا ارتکاز معلوم کرنا چاہتے ہوں تو آپ کو مساوات (8.5) کا اینٹی لوگ لینا ہوگا، جیسا کہ درج ذیل ہے،','که تاسو د یو محلول pH ارزښت پېژنئ او غواړئ د H⁺ آیون غلظت محاسبه کړئ نو تاسو باید د معادلې (8.5) انټي لوګ واخلئ، لکه څنګه چې لاندې ده،')
add(s,'a3','You can also find simply the pOH, a measure of hydroxide-ion concentration similar to the pH. The pOH is defined as the negative logarithm of the OH⁻ concentration in moles per dm³.','آپ آسانی سے pOH بھی معلوم کر سکتے ہیں، جو pH کی طرح ہائیڈرو آکسائیڈ آئن کے ارتکاز کا پیمانہ ہے۔ pOH کی تعریف OH⁻ کے ارتکاز کے منفی لوگارتھم کے طور پر کی جاتی ہے، مول فی dm³ میں۔','تاسو کولای شئ په اسانۍ سره pOH هم ومومئ، چې د pH په څېر د هایدروکسایډ آیون د غلظت یو پیمانه ده. pOH د OH⁻ د غلظت د منفي لوګاریتم په توګه تعریفېږي، په مولونو په هر dm³ کې.')
add(s,'a4','A solution at 25°C has a [OH⁻] of 1 × 10⁻⁷ M.','25°C پر ایک محلول کا [OH⁻] 1 × 10⁻⁷ M ہوتا ہے۔','په 25°C کې یو محلول [OH⁻] لري چې 1 × 10⁻⁷ M دی.')
add(s,'a5','Therefore, the pOH is 7.0.','لہٰذا pOH 7.0 ہے۔','نو pOH 7.0 دی.')
add(s,'a6','For example, the pH of pure water at 25°C is 7 and is said to be neutral; that is, it is neither acidic nor basic, because the concentrations of H⁺ and OH⁻ are equal. Solutions that contain more H⁺ ions than OH⁻ ions have pH values less than 7, and solutions that contain fewer H⁺ ions than OH⁻ ions have pH values greater than 7.','مثال کے طور پر 25°C پر خالص پانی کا pH 7 ہے اور اسے معتدل کہا جاتا ہے؛ یعنی یہ نہ تیزابی ہے نہ اساسی، کیونکہ H⁺ اور OH⁻ کے ارتکاز برابر ہیں۔ وہ محلول جن میں OH⁻ آئنوں سے زیادہ H⁺ آئن ہوں ان کے pH کی قیمتیں 7 سے کم ہوتی ہیں اور وہ محلول جن میں OH⁻ آئنوں سے کم H⁺ آئن ہوں ان کے pH کی قیمتیں 7 سے زیادہ ہوتی ہیں۔','د بېلګې په توګه په 25°C کې د خالصو اوبو pH 7 دی او خنثی بلل کېږي؛ یعنې دا نه اسیدي دی نه القلي، ځکه چې د H⁺ او OH⁻ غلظتونه مساوي دي. هغه محلولونه چې له OH⁻ آیونونو څخه ډېر H⁺ آیونونه لري د pH ارزښتونه یې له 7 څخه کم دي او هغه محلولونه چې له OH⁻ آیونونو څخه لږ H⁺ آیونونه لري د pH ارزښتونه یې له 7 څخه ډېر دي.')
add(s,'a7','As you know that K_w = [H⁺][OH⁻] = 1.0 × 10⁻¹⁴ at 25°C','جیسا کہ آپ جانتے ہیں کہ 25°C پر K_w = [H⁺][OH⁻] = 1.0 × 10⁻¹⁴ ہے','لکه څنګه چې تاسو پوهېږئ چې په 25°C کې K_w = [H⁺][OH⁻] = 1.0 × 10⁻¹⁴ دی')
add(s,'a8','The pK_w is defined as the negative logarithm of K_w. It can be written as,','pK_w کی تعریف K_w کے منفی لوگارتھم کے طور پر کی جاتی ہے۔ اسے اس طرح لکھا جا سکتا ہے،','pK_w د K_w د منفي لوګاریتم په توګه تعریفېږي. دا داسې لیکل کېدای شي،')
add(s,'a9','Then because, pK_w = −logK_w = [H⁺][OH⁻] = −log(1.0 × 10⁻¹⁴)','پھر چونکہ، pK_w = −logK_w = [H⁺][OH⁻] = −log(1.0 × 10⁻¹⁴)','بیا ځکه، pK_w = −logK_w = [H⁺][OH⁻] = −log(1.0 × 10⁻¹⁴)')
add(s,'a10','Taking the logarithm of both sides of the equation,','مساوات کے دونوں اطراف کا لوگارتھم لینے پر،','د معادلې د دواړو اړخونو لوګاریتم اخیستلو سره،')
add(s,'a11','You will get,','آپ کو ملے گا،','تاسو به ترلاسه کړئ،')
add(s,'a12','Hence, pH + pOH = 14.00','لہٰذا pH + pOH = 14.00','نو pH + pOH = 14.00')
add(s,'a13','The value of pK_w decreases with increase in temperature.','pK_w کی قیمت درجہ حرارت بڑھنے کے ساتھ گھٹتی ہے۔','د pK_w ارزښت د تودوخې په زیاتېدو سره کمېږي.')
add(s,'rc-h','Reading Check','مطالعہ کی جانچ','د لوستلو ازموینه',kind='heading')
add(s,'rc1','Define pH, pOH and pK_w.','pH، pOH اور pK_w کی تعریف کریں۔','pH، pOH او pK_w تعریف کړئ.',role='question')
F.p('a1','a2')
F.e('e86',r'[\mathrm{H^+}]=10^{-\mathrm{pH}}\qquad(8.6)','[H⁺] = 10^(−pH)   (8.6)')
F.p('a3')
F.e('p1',r'\mathrm{pOH}=-\log[\mathrm{OH^-}]','pOH = −log[OH⁻]')
F.p('a4')
F.e('e87',r'\mathrm{pOH}=-\log[\mathrm{OH^-}]\qquad(8.7)','pOH = −log[OH⁻]   (8.7)')
F.e('p2',r'\mathrm{pOH}=-\log(1\times10^{-7})','pOH = −log(1 × 10⁻⁷)')
F.e('p3',r'\mathrm{pOH}=-(-7)=7','pOH = −(−7) = 7')
F.p('a5','a6','a7','a8')
F.e('k1',r'\mathrm{p}K_w=-\log K_w','pK_w = −log K_w')
F.p('a9','a10')
F.e('k2',r'[\mathrm{H^+}][\mathrm{OH^-}]=1.0\times10^{-14}','[H⁺][OH⁻] = 1.0 × 10⁻¹⁴')
F.p('a11')
F.e('k3',r'\log[\mathrm{H^+}]+\log[\mathrm{OH^-}]=\log(1.0\times10^{-14})','log[H⁺] + log[OH⁻] = log(1.0 × 10⁻¹⁴)')
F.e('k4',r'(-\log[\mathrm{H^+}])+(-\log[\mathrm{OH^-}])=-\log(1.0\times10^{-14})','(−log[H⁺]) + (−log[OH⁻]) = −log(1.0 × 10⁻¹⁴)')
F.p('a12')
F.e('k5',r'\mathrm{p}K_w=14\ \text{at }25^\circ\mathrm{C}','pK_w = 14 at 25°C')
F.p('a13')
F.e('e88',r'\mathrm{p}K_w=\mathrm{pH}+\mathrm{pOH}=14.00\qquad(8.8)','pK_w = pH + pOH = 14.00   (8.8)')
F.p('rc-h','rc1')
F.done()
